    assert_eq!(code(&responses[3]), "ReceiptHandleExpired");
    assert_eq!(responses[4]["Messages"][0]["ReceiptHandle"], json!("r-2"));
    assert_eq!(responses[4]["Messages"][0]["ReceiveCount"], json!(2));
}

#[test]
fn delete_and_change_visibility_check_handles() {
    let responses = run(&[
