        send_fifo("f.fifo", "a2", "a", "2"),
        send_fifo("f.fifo", "b1", "b", "3"),
        send_fifo("f.fifo", "b2", "b", "4"),
        receive_up_to("f.fifo", 10),
        receive_up_to("f.fifo", 10),
        delete("f.fifo", "r-1"),
        receive_up_to("f.fifo", 10),
