    assert_eq!(delivered(&responses[8]), vec![("m-2".into(), "a2".into())]);
    assert_eq!(responses[8]["Messages"][0]["GroupId"], json!("a"));
    assert_eq!(responses[8]["Messages"][0]["SequenceNumber"], json!(2));
}

